"""
Microsoft-Graph-Mailer und -Reader.

Das Modul versendet und liest E-Mails ueber die Microsoft Graph API per
OAuth2 Client-Credentials-Flow. Es fuehrt keine SMTP- oder Datenbankzugriffe aus.
"""

import base64
import json
import logging
from pathlib import Path
from typing import Any, Literal

import requests

from ..config_service import decode_required_secret

logger = logging.getLogger(__name__)

JsonObject = dict[str, Any]
Attachment = dict[str, str]


class _MsGraphBase:
    """Basisklasse mit OAuth2-Authentifizierung fuer die Microsoft Graph API."""

    def __init__(
        self,
        tenant_id: str,
        client_id: str,
        client_secret: str,
        timeout: int = 10,
    ) -> None:
        """Initialisiert gemeinsame Graph-API-Zugangsdaten."""
        self.tenant_id = tenant_id
        self.client_id = client_id
        self.client_secret = client_secret
        self.timeout = timeout

    def _get_oauth_token(self) -> str:
        """Holt ein OAuth2-Token via Client-Credentials-Flow."""
        url = f"https://login.microsoftonline.com/{self.tenant_id}/oauth2/v2.0/token"
        payload = {
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "grant_type": "client_credentials",
            "scope": "https://graph.microsoft.com/.default",
        }
        logger.debug("Hole OAuth2-Token fuer Tenant %s", self.tenant_id)
        response = requests.post(
            url,
            data=payload,
            headers={"content-type": "application/x-www-form-urlencoded"},
            timeout=self.timeout,
        )
        response.raise_for_status()

        response_data = response.json()
        if not isinstance(response_data, dict):
            raise ValueError("OAuth2-Token-Antwort ist kein JSON-Objekt.")

        token = response_data.get("access_token")
        if not isinstance(token, str) or not token:
            raise ValueError("OAuth2-Token-Antwort enthaelt kein access_token.")

        logger.debug("OAuth2-Token erfolgreich abgerufen")
        return token


class MsGraphMailer(_MsGraphBase):
    """Versendet E-Mails ueber die Microsoft Graph API.

    Benoetigt die App-Berechtigung ``Mail.Send`` in Azure AD.

    Args:
        tenant_id: Azure AD Tenant-ID.
        client_id: App-Registrierungs-Client-ID.
        client_secret: App-Registrierungs-Client-Secret.
        sender: E-Mail-Adresse des Absenders.
        default_recipients: Optionale Standard-Empfaenger, die genutzt werden,
            wenn beim Aufruf von send() keine Empfaenger angegeben werden.
        timeout: HTTP-Timeout in Sekunden.
    """

    def __init__(
        self,
        tenant_id: str,
        client_id: str,
        client_secret: str,
        sender: str,
        default_recipients: list[str] | None = None,
        timeout: int = 10,
    ) -> None:
        """Initialisiert einen Mailer fuer ein bestimmtes Absenderpostfach."""
        super().__init__(tenant_id, client_id, client_secret, timeout)
        self.sender = sender
        self.default_recipients = default_recipients or []

    @staticmethod
    def _build_attachment(path: str | Path) -> Attachment:
        """Liest eine datei und gibt sie als Graph-API-Anhang-Dict zurueck."""
        file_path = Path(path)
        logger.debug("Lese Anhang: %s", file_path.name)
        with file_path.open("rb") as file:
            content = base64.b64encode(file.read()).decode("utf-8")
        return {
            "@odata.type": "#microsoft.graph.fileAttachment",
            "name": file_path.name,
            "contentType": "application/octet-stream",
            "contentBytes": content,
        }

    def send(
        self,
        subject: str,
        body: str,
        to: list[str] | None = None,
        cc: list[str] | None = None,
        attachments: list[str | Path] | None = None,
        body_type: Literal["Text", "HTML"] = "Text",
        save_to_sent: bool = False,
    ) -> None:
        """Versendet eine E-Mail.

        Args:
            subject: Betreff der E-Mail.
            body: Inhalt der E-Mail.
            to: Empfaengerliste. Wird sie nicht angegeben, werden
                ``default_recipients`` verwendet.
            cc: Optionale CC-Empfaengerliste.
            attachments: Optionale Liste von Dateipfaden als Anhang.
            body_type: ``"Text"`` oder ``"HTML"``.
            save_to_sent: E-Mail im Gesendete-Ordner speichern.

        Raises:
            ValueError: Wenn keine Empfaenger angegeben wurden.
            requests.HTTPError: Bei HTTP-Fehlern der Graph-API.
        """
        recipients = to if to is not None else self.default_recipients
        if not recipients:
            raise ValueError("Keine Empfaenger angegeben. Bitte 'to' uebergeben oder 'default_recipients' setzen.")

        logger.info("Sende E-Mail '%s' von %s an %s", subject, self.sender, recipients)

        token = self._get_oauth_token()
        payload: JsonObject = {
            "message": {
                "subject": subject,
                "body": {"contentType": body_type, "content": body},
                "toRecipients": [{"emailAddress": {"address": recipient}} for recipient in recipients],
                "ccRecipients": [{"emailAddress": {"address": recipient}} for recipient in (cc or [])],
                "attachments": [self._build_attachment(attachment) for attachment in (attachments or [])],
            },
            "saveToSentItems": str(save_to_sent).lower(),
        }

        response = requests.post(
            f"https://graph.microsoft.com/v1.0/users/{self.sender}/sendMail",
            data=json.dumps(payload),
            headers={
                "content-type": "application/json",
                "authorization": f"Bearer {token}",
            },
            timeout=self.timeout,
        )
        response.raise_for_status()
        logger.info("E-Mail '%s' erfolgreich versendet (status %s)", subject, response.status_code)


class MsGraphMailReader(_MsGraphBase):
    """Liest E-Mails aus einem Postfach ueber die Microsoft Graph API.

    Benoetigt die App-Berechtigung ``Mail.Read`` in Azure AD.
    """

    def __init__(
        self,
        tenant_id: str,
        client_id: str,
        client_secret: str,
        mailbox: str,
        timeout: int = 10,
    ) -> None:
        """Initialisiert einen Reader fuer ein bestimmtes Postfach."""
        super().__init__(tenant_id, client_id, client_secret, timeout)
        self.mailbox = mailbox

    def fetch(
        self,
        folder: str = "inbox",
        top: int = 10,
        filter_query: str | None = None,
    ) -> list[JsonObject]:
        """Liest E-Mails aus einem Postfach-Ordner.

        Args:
            folder: Ordner, z. B. ``"inbox"`` oder ``"sentItems"``.
            top: Maximale Anzahl zurueckgegebener Nachrichten.
            filter_query: OData-Filterausdruck.

        Returns:
            Liste von Nachrichten-Dicts im Graph-API-Format.
        """
        token = self._get_oauth_token()

        params: dict[str, str | int] = {"$top": top, "$orderby": "receivedDateTime desc"}
        if filter_query:
            params["$filter"] = filter_query

        logger.info("Lese E-Mails aus Postfach %s/%s (top=%s)", self.mailbox, folder, top)
        response = requests.get(
            f"https://graph.microsoft.com/v1.0/users/{self.mailbox}/mailFolders/{folder}/messages",
            headers={"authorization": f"Bearer {token}"},
            params=params,
            timeout=self.timeout,
        )
        response.raise_for_status()
        messages = _extract_graph_values(response)
        logger.info("%s Nachricht(en) abgerufen", len(messages))
        return messages

    def fetch_attachments(self, message_id: str) -> list[JsonObject]:
        """Liest Anhaenge einer bestimmten Nachricht.

        Args:
            message_id: ID der Nachricht aus ``fetch()``.

        Returns:
            Liste von Anhang-Dicts mit ``name``, ``contentType`` und ``contentBytes``.
        """
        token = self._get_oauth_token()

        logger.debug("Lese Anhaenge fuer Nachricht %s", message_id)
        response = requests.get(
            f"https://graph.microsoft.com/v1.0/users/{self.mailbox}/messages/{message_id}/attachments",
            headers={"authorization": f"Bearer {token}"},
            timeout=self.timeout,
        )
        response.raise_for_status()
        attachments = _extract_graph_values(response)
        logger.debug("%s Anhang/Anhaenge gefunden", len(attachments))
        return attachments


def _extract_graph_values(response: requests.Response) -> list[JsonObject]:
    """Liest die Graph-API-`value`-Liste aus einer JSON-Response."""
    response_data = response.json()
    if not isinstance(response_data, dict):
        raise ValueError("Graph-API-Antwort ist kein JSON-Objekt.")

    values = response_data.get("value", [])
    if not isinstance(values, list):
        raise ValueError("Graph-API-Antwort enthaelt keine value-Liste.")

    result: list[JsonObject] = []
    for item in values:
        if not isinstance(item, dict):
            raise ValueError("Graph-API-value enthaelt ein Element, das kein JSON-Objekt ist.")
        result.append(item)
    return result


def mailer_from_encrypted_env(
    sender: str,
    default_recipients: list[str] | None = None,
) -> MsGraphMailer:
    """Erstellt einen ``MsGraphMailer`` aus verschluesselten Umgebungsvariablen."""
    logger.debug("Erstelle MsGraphMailer aus verschluesselten Umgebungsvariablen")
    context = "Microsoft Graph"
    return MsGraphMailer(
        tenant_id=decode_required_secret("MS_GRAPH_TENANT_ID", context=context),
        client_id=decode_required_secret("MS_GRAPH_CLIENT_ID", context=context),
        client_secret=decode_required_secret("MS_GRAPH_CLIENT_SECRET", context=context),
        sender=sender,
        default_recipients=default_recipients,
    )


def reader_from_encrypted_env(mailbox: str) -> MsGraphMailReader:
    """Erstellt einen ``MsGraphMailReader`` aus verschluesselten Umgebungsvariablen."""
    logger.debug("Erstelle MsGraphMailReader aus verschluesselten Umgebungsvariablen")
    context = "Microsoft Graph"
    return MsGraphMailReader(
        tenant_id=decode_required_secret("MS_GRAPH_TENANT_ID", context=context),
        client_id=decode_required_secret("MS_GRAPH_CLIENT_ID", context=context),
        client_secret=decode_required_secret("MS_GRAPH_CLIENT_SECRET", context=context),
        mailbox=mailbox,
    )
